//О депутате, открыть полную информацию
const more = document.querySelector('#about__more')
if (more) {

    more.onclick = function () {
        //document.querySelector('.deputat__about').classList.add('open');
        document.querySelector('.deputat__about').classList.toggle('open')
        if (document.querySelector('.deputat__about').classList.contains('open')) {
            more.innerHTML = 'Свернуть';
        } else {
            more.innerHTML = 'Показать';
        }

    }

}

//Аккордион в муниципальной службе
let acc = document.getElementsByClassName("accordion");
for (let i = 0; i < acc.length; i++) {
    acc[i].addEventListener("click", function () {
        this.classList.toggle("active");
        let panel = this.nextElementSibling;
        if (panel.style.display === "block") {
            panel.style.display = "none";
        } else {
            panel.style.display = "block";
        }
    });
}





//Клик на синюю кнопку в моб версии
const footerArrow = document.querySelectorAll('.footer__arrow')
footerArrow.forEach(el => {
    el.onclick = function () {
        $(this).parent().parent().toggleClass('open');
    }
});

//ползунок во вкладке история
function historyBlocks(value) {
    let maxId = 102;//Максимальное значение года по ID, смотреть в админке
    let minId = 95;//Максимальное значение года по ID, смотреть в админке
    document.querySelector('#evolution__years-start').textContent = value;
    for (let i = value; i <= maxId; i++) {
        let open = '#block-' + i;
        document.querySelector(open).classList.remove('open');
    }
    for (value; value >= minId; value--) {
        let val = '#block-' + value;
        document.querySelector(val).classList.add('open');
    }

}

